"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["94221"],{21911(e){e.exports=JSON.parse('{"id":"FIN-108","slug":"financial-statement","term":"Financial Statement","also_known_as":[],"difficulty":"Beginner","definition":"A financial statement is a formal report that summarises a business\'s financial activity and position. The main ones are the balance sheet, the income statement and the cash flow statement.","explanation":["Financial statements turn thousands of individual transactions into a few clear reports that people outside the business can understand.","Each statement answers a different question. The balance sheet shows what the business owns and owes at a particular date. The income statement shows how much revenue was earned and what expenses were incurred over a period, ending with profit or loss. The cash flow statement shows how cash moved in and out over the same period. A fourth statement shows changes in equity, and the notes explain the figures in detail.","The statements are connected. Profit from the income statement increases equity on the balance sheet. The cash flow statement explains why the cash balance on the balance sheet changed between two dates.","Investors use financial statements to judge profitability and value, lenders to judge whether loans can be repaid, managers to make decisions and tax authorities to check tax owed. For many companies, the statements must follow GAAP or IFRS and be checked by independent auditors."],"note":"","total":1725,"prev":{"slug":"financial-stability-board","term":"Financial Stability Board (FSB)"},"next":{"slug":"financial-well-being","term":"Financial Well-Being"}}')}}]);